using System;
using System.Numerics;

// 방향 벡터 규약: toLight = 표면 -> 광원, toView = 표면 -> 카메라.
// normal / toLight / toView 는 정규화되어 있지 않을 수 있다.
public static class Lighting
{
    // x 를 [0, 1] 로 자른다 (HLSL 의 saturate).
    public static float Saturate(float x)
    {
        throw new NotImplementedException();
    }

    // Lambert 디퓨즈 항: saturate(dot(N, L)). N, L 은 정규화한 뒤 사용한다.
    // normal 또는 toLight 의 길이가 0 이면 0.
    public static float Diffuse(Vector3 normal, Vector3 toLight)
    {
        throw new NotImplementedException();
    }

    // Blinn-Phong 스페큘러 항: pow(saturate(dot(N, H)), shininess).
    // H = normalize(L + V) 이고, 여기서 L, V 는 각각 정규화한 벡터다.
    // dot(N, L) <= 0 (빛이 표면 뒤쪽) 이면 0. 길이가 0 인 입력이 있거나 L + V 가 0 벡터면 0.
    // shininess >= 1 이라고 가정한다.
    public static float Specular(Vector3 normal, Vector3 toLight, Vector3 toView, float shininess)
    {
        throw new NotImplementedException();
    }

    // 최종 색: lightColor * (albedo * diffuse + specularColor * specular), 성분별 곱.
    public static Vector3 Shade(Vector3 normal, Vector3 toLight, Vector3 toView,
                                Vector3 albedo, Vector3 specularColor, Vector3 lightColor, float shininess)
    {
        throw new NotImplementedException();
    }
}

problems.solutionCode:
using System;
using System.Numerics;

public static class Lighting
{
    private const float MinLengthSq = 1e-12f;

    public static float Saturate(float x)
    {
        if (x < 0f) return 0f;
        if (x > 1f) return 1f;
        return x;
    }

    public static float Diffuse(Vector3 normal, Vector3 toLight)
    {
        if (!TryNormalize(normal, out Vector3 n) || !TryNormalize(toLight, out Vector3 l)) return 0f;
        return Saturate(Vector3.Dot(n, l));
    }

    public static float Specular(Vector3 normal, Vector3 toLight, Vector3 toView, float shininess)
    {
        if (!TryNormalize(normal, out Vector3 n) || !TryNormalize(toLight, out Vector3 l)
            || !TryNormalize(toView, out Vector3 v)) return 0f;

        // 빛이 표면 뒤쪽에 있으면 하이라이트도 없다.
        if (Vector3.Dot(n, l) <= 0f) return 0f;

        // 하프 벡터는 "정규화한" L 과 V 의 합을 다시 정규화한 것.
        // L 과 V 가 정반대면 합이 0 벡터가 되므로 나누기 전에 걸러낸다.
        if (!TryNormalize(l + v, out Vector3 h)) return 0f;

        return MathF.Pow(Saturate(Vector3.Dot(n, h)), shininess);
    }

    public static Vector3 Shade(Vector3 normal, Vector3 toLight, Vector3 toView,
                                Vector3 albedo, Vector3 specularColor, Vector3 lightColor, float shininess)
    {
        float diffuse = Diffuse(normal, toLight);
        float specular = Specular(normal, toLight, toView, shininess);
        return lightColor * (albedo * diffuse + specularColor * specular);
    }

    // 길이가 0 에 가까우면 false. 0 벡터를 길이로 나누면 0 / 0 = NaN 이 된다.
    private static bool TryNormalize(Vector3 value, out Vector3 result)
    {
        float lengthSq = value.LengthSquared();
        if (!(lengthSq > MinLengthSq))
        {
            result = Vector3.Zero;
            return false;
        }
        result = value / MathF.Sqrt(lengthSq);
        return true;
    }
}

