using System;
using System.Collections.Generic;
using System.Numerics;

public static class AlphaBlend
{
    public static Vector4 Premultiply(Vector4 straight)
    {
        float a = straight.W;
        return new Vector4(straight.X * a, straight.Y * a, straight.Z * a, a);
    }

    public static Vector4 Unpremultiply(Vector4 premultiplied)
    {
        float a = premultiplied.W;
        // 알파가 0 이면 나눌 수 없다. 덮는 것이 없으므로 색도 0 으로 둔다.
        if (a <= 0f) return Vector4.Zero;
        float inv = 1f / a;
        return new Vector4(premultiplied.X * inv, premultiplied.Y * inv, premultiplied.Z * inv, a);
    }

    public static Vector4 OverStraight(Vector4 src, Vector4 dst)
    {
        // dst 가 src 에 가려지고 남는 몫
        float dstWeight = dst.W * (1f - src.W);
        float outA = src.W + dstWeight;
        if (outA <= 0f) return Vector4.Zero;

        float inv = 1f / outA;
        return new Vector4(
            (src.X * src.W + dst.X * dstWeight) * inv,
            (src.Y * src.W + dst.Y * dstWeight) * inv,
            (src.Z * src.W + dst.Z * dstWeight) * inv,
            outA);
    }

    public static Vector4 OverPremultiplied(Vector4 src, Vector4 dst)
    {
        // RGB 와 A 가 같은 식을 따르므로 벡터 연산 한 줄이면 된다.
        return src + dst * (1f - src.W);
    }

    public static Vector4 CompositeLayers(IReadOnlyList<Vector4> straightLayersBottomToTop)
    {
        // 누적값은 premultiplied 로 들고 다닌다: 레이어마다 나눗셈을 하지 않아도 된다.
        Vector4 acc = Vector4.Zero;
        for (int i = 0; i < straightLayersBottomToTop.Count; i++)
        {
            acc = OverPremultiplied(Premultiply(straightLayersBottomToTop[i]), acc);
        }
        // 나눗셈은 마지막에 한 번만.
        return Unpremultiply(acc);
    }
}

