using System;

public enum WrapMode
{
    Clamp,
    Repeat
}

public static class TextureSampler
{
    public static int WrapIndex(int index, int size, WrapMode mode)
    {
        if (mode == WrapMode.Repeat)
        {
            // C# 의 % 는 피제수의 부호를 따르므로 음수 나머지를 한 번 보정한다.
            int m = index % size;
            return m < 0 ? m + size : m;
        }

        if (index < 0) return 0;
        if (index >= size) return size - 1;
        return index;
    }

    public static float SampleBilinear(float[] texels, int width, int height, float u, float v, WrapMode mode)
    {
        // 텍셀 중심이 정수가 되는 좌표계로 옮긴다: 중심 (x + 0.5) / width  ->  x
        float fx = u * width - 0.5f;
        float fy = v * height - 0.5f;

        // 음수에서도 "왼쪽/아래 이웃"이 나오도록 버림이 아니라 내림을 쓴다.
        float floorX = MathF.Floor(fx);
        float floorY = MathF.Floor(fy);
        float tx = fx - floorX; // 0..1, 오른쪽 이웃의 가중치
        float ty = fy - floorY; // 0..1, 위쪽(y + 1) 이웃의 가중치

        int x0 = WrapIndex((int)floorX, width, mode);
        int x1 = WrapIndex((int)floorX + 1, width, mode);
        int y0 = WrapIndex((int)floorY, height, mode);
        int y1 = WrapIndex((int)floorY + 1, height, mode);

        float row0 = Lerp(texels[y0 * width + x0], texels[y0 * width + x1], tx);
        float row1 = Lerp(texels[y1 * width + x0], texels[y1 * width + x1], tx);
        return Lerp(row0, row1, ty);
    }

    private static float Lerp(float a, float b, float t)
    {
        return a + (b - a) * t;
    }
}

