        int y0 = RefWrap((long)fly, h, mode), y1 = RefWrap((long)fly + 1, h, mode);
        double a = t[y0 * w + x0] * (1 - tx) + t[y0 * w + x1] * tx;
        double b = t[y1 * w + x0] * (1 - tx) + t[y1 * w + x1] * tx;
        return a * (1 - ty) + b * ty;
    }

    static readonly float[] Row4 = { 0f, 1f, 2f, 3f };                 // 4 x 1
    static readonly float[] Grid32 = { 1f, 2f, 3f, 4f, 5f, 6f };       // 3 x 2: 0번 행 = 1 2 3, 1번 행 = 4 5 6
