                        ?? S(Grid32, 3, 2, (x + 0.5) / 3.0, (y + 0.5) / 2.0, WrapMode.Repeat, Grid32[y * 3 + x]);
                    if (e != null) return e + " (텍셀 (" + x + ", " + y + ") 의 중심)";
