                ?? S(col, 1, 3, 0.5, 0.0, WrapMode.Repeat, 5.0) ?? S(col, 1, 3, 0.5, 0.0, WrapMode.Clamp, 2.0);
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(31337);
