using System;

public enum WrapMode
{
    Clamp,  // 범위를 벗어난 텍셀 좌표는 가장자리 텍셀로 고정
    Repeat  // 범위를 벗어난 텍셀 좌표는 반대쪽에서 이어진다
}

// 전장의 안개 마스크(한 채널, 0 = 가려짐 ~ 1 = 밝혀짐)를 CPU 에서 읽는 텍스처.
//
// 저장 순서: pixels 는 이미지 파일 순서다. 맨 위 행부터, 각 행은 왼쪽부터. pixels[row * Width + column]
// UV 규약  : (0, 0) 은 텍스처의 왼쪽 아래, (1, 1) 은 오른쪽 위.
// 텍셀 좌표: (x, y) 에서 x 는 왼쪽부터, y 는 아래부터 센다.
//            텍셀 (x, y) 의 중심은 u = (x + 0.5) / Width, v = (y + 0.5) / Height.
public sealed class CpuTexture
{
    private readonly float[] _pixels;

    public int Width { get; }
    public int Height { get; }

    public CpuTexture(int width, int height, float[] pixels)
    {
        if (width < 1 || height < 1) throw new ArgumentOutOfRangeException(nameof(width));
        if (pixels == null || pixels.Length != width * height) throw new ArgumentException("pixels 의 길이가 width * height 가 아니다");
        Width = width;
        Height = height;
        _pixels = pixels;
    }

    // 텍셀 좌표 (x, y) 의 값. 범위를 벗어난 좌표는 wrap 규칙으로 옮긴다.
    public float GetTexel(int x, int y, WrapMode wrap)
    {
        int tx = WrapIndex(x, Width, wrap);
        int ty = WrapIndex(y, Height, wrap);
        return _pixels[ty * Width + tx];
    }

    // (u, v) 가 속한 텍셀 하나의 값 (포인트 샘플링).
    public float SamplePoint(float u, float v, WrapMode wrap)
    {
        int x = (int)MathF.Floor(u * Width);
        int y = (int)MathF.Floor(v * Height);
        return GetTexel(x, y, wrap);
    }

    // (u, v) 를 둘러싼 텍셀 중심 4개를 거리에 따라 섞은 값 (바이리니어 샘플링).
    public float SampleBilinear(float u, float v, WrapMode wrap)
    {
        float fx = u * Width;
        float fy = v * Height;
        int x0 = (int)MathF.Floor(fx);
        int y0 = (int)MathF.Floor(fy);
        float tx = fx - x0;
        float ty = fy - y0;

        float lower = Lerp(GetTexel(x0, y0, wrap), GetTexel(x0 + 1, y0, wrap), tx);
        float upper = Lerp(GetTexel(x0, y0 + 1, wrap), GetTexel(x0 + 1, y0 + 1, wrap), tx);
        return Lerp(lower, upper, ty);
    }

    private static int WrapIndex(int index, int size, WrapMode wrap)
    {
        if (wrap == WrapMode.Repeat) return index % size;
        return Math.Min(index, size - 1);
    }

    private static float Lerp(float a, float b, float t)
    {
        return a + (b - a) * t;
    }
}

