public static class __Judge
{
    const double Eps = 1e-4;

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static bool Near(float got, double exp) { return !float.IsNaN(got) && System.Math.Abs(got - exp) <= Eps; }

    static string T(CpuTexture t, int x, int y, WrapMode m, double exp)
    {
        float got = t.GetTexel(x, y, m);
        return Near(got, exp) ? null : "GetTexel(" + x + ", " + y + ", " + m + ") [" + t.Width + "x" + t.Height + "]: 기대 " + exp.ToString("0.#####") + ", 결과 " + got;
    }
    static string P(CpuTexture t, double u, double v, WrapMode m, double exp)
    {
        float got = t.SamplePoint((float)u, (float)v, m);
        return Near(got, exp) ? null : "SamplePoint(u=" + u + ", v=" + v + ", " + m + ") [" + t.Width + "x" + t.Height + "]: 기대 " + exp.ToString("0.#####") + ", 결과 " + got;
    }
    static string B(CpuTexture t, double u, double v, WrapMode m, double exp)
    {
        float got = t.SampleBilinear((float)u, (float)v, m);
        return Near(got, exp) ? null : "SampleBilinear(u=" + u + ", v=" + v + ", " + m + ") [" + t.Width + "x" + t.Height + "]: 기대 " + exp.ToString("0.#####") + ", 결과 " + got;
    }

